        load: loaded.kind ?? scope,
        sessions: loaded.sessions.length,
        last: window.last,
        maxAgeDays: window.maxAgeDays,
        installAgeDays: report.installAgeDays,
        candidates,
70→        recent,
        ...(loaded.sessions.length === 0 ? { reason: "no-sessions" } : {}),
      });
      await exit(0);
      return;
