    message: "Edit key",
    options: keys.map((k) => ({
      value: k.key,
      label: k.key,
      hint: displayConfigValue(k.key, getNestedValue(asRecord, k.key)),
    })),
    output: stderr,
  });
  if (isCancel(choice)) {
    cancelled();
    return;
